mapper.select:
select type_name,type_code,count(1) as totalNum from risk_source_ledger where type_code in
#{item}
GROUP BY type_code order by totalNum desc

SELECT COUNT( rsl.id ) AS DEVICE_NUM, COALESCE ( SUM( IF ( rsl.STATUS = 'EXPIRE', 1, 0 )), 0 ) AS expire_num, rsl.type_code AS DEVICE_CODE FROM risk_source_ledger rsl WHERE 1=1
and rsl.type_code IN
#{deviceName}
AND rsl.create_time between #{param.period.begin} and #{param.period.end}
GROUP BY rsl.type_code

select a.*,
b.id as extendInfoId,
b.ledger_id,
b.receive_user_type,
b.purchasing_date,
b.efficiency,
b.plate_number,
b.insurance,
b.brand,
b.electron_mobile_type,
b.electron_mobile_colour
from risk_source_ledger a
left join risk_source_ledger_extend_info b on a.id = b.ledger_id


        and a.id in

            #{id}



        a.create_time between #{param.period.begin} and #{param.period.end}


        and a.stall_id = #{param.stallId}


        and a.area_id like concat('%', #{param.areaId},'%')


        and a.type_code = #{param.typeCode}


        and a.site_point_id=#{param.sitePointId}


        and a.receive_dep_id = #{param.receiveDepId}


        and a.maintenance_dep_id = #{param.maintenanceDepId}


        and a.status = #{param.status}


        and a.usage_date = #{param.usageDate}


        and b.purchasing_date = #{param.purchasingDate}


        and b.receive_user_type = #{param.receiveUserType}


        and ( a.name like concat('%',#{param.keyword},'%')
        or a.serial_number like concat('%',#{param.keyword},'%')
        or a.receive_user_name like concat('%',#{param.keyword},'%')
        or b.plate_number like concat('%',#{param.keyword},'%')
        )


        and b.electron_mobile_type = #{param.electronMobileType}


        and b.brand = #{param.brand}


        and a.type_code in

            #{type}



order by a.create_time desc

select
*
from
risk_source_ledger


        and update_time BETWEEN #{period.begin}
        AND #{period.end}

    and type_code in

        #{code}


order by update_time asc

SELECT COUNT( 1 ) AS typeNum, a.type_code FROM risk_source_ledger a WHERE a.lat_and_lon IS NOT NULL AND a.lat_and_lon != '' and a.type_code IN
#{typeCode}
GROUP BY a.type_code
